1	//! `rtk audit` — SLSA provenance attestation export (codeflow Phase 5).
2	//!
3	//! Usage:
4	//!   rtk audit                        — SLSA export, last 90 days
5	//!   rtk audit --format slsa          — explicit format
6	//!   rtk audit --range 30d|90d|1y|all — date range
7	//!   rtk audit --project <name>       — filter by project path substring
8	//!   rtk audit --dev <id>             — filter by developer id
9	//!   rtk audit --output <dir>         — custom output directory (default: ./codeflow-audit/)
10	//!   rtk audit --json                 — machine-readable summary to stdout
11	
12	use anyhow::{Context, Result};
13	use colored::Colorize;
14	
15	use crate::compliance::report_common::{
16	    query_provenance_records, range_to_since, stats_from_records, AuditFormat,
17	};
18	use crate::compliance::slsa_export::generate_slsa;
19	
20	// ── Public entry point ────────────────────────────────────────────────────────
21	
22	pub struct AuditArgs {
23	    pub format: String,
24	    pub range: String,
25	    pub project: Option<String>,
26	    pub dev: Option<String>,
27	    pub output: Option<String>,
28	    pub json: bool,
29	}
30	
31	impl Default for AuditArgs {
32	    fn default() -> Self {
33	        Self {
34	            format: "slsa".to_string(),
35	            range: "90d".to_string(),
36	            project: None,
37	            dev: None,
38	            output: None,
39	            json: false,
40	        }
41	    }
42	}
43	
44	pub fn run(args: &AuditArgs) -> Result<i32> {
45	    let fmt = AuditFormat::from_str(&args.format).unwrap_or_else(|| {
46	        // Unknown format → default to SLSA and warn
47	        eprintln!(
48	            "[rtk audit] unknown format '{}', defaulting to slsa",
49	            args.format
50	        );
51	        AuditFormat::Slsa
52	    });
53	
54	    // Non-SLSA formats: stub — coming in a future release.
55	    match &fmt {
56	        AuditFormat::CycloneDx | AuditFormat::Soc2 | AuditFormat::EuAiAct | AuditFormat::All => {
57	            return run_coming_soon(&fmt);
58	        }
59	        AuditFormat::Slsa => {}
60	    }
61	
62	    run_slsa(args)
63	}
64	
65	// ── SLSA export ───────────────────────────────────────────────────────────────
66	
67	fn run_slsa(args: &AuditArgs) -> Result<i32> {
68	    let since = range_to_since(&args.range);
69	    let since_str = since.as_deref();
70	
71	    let records = query_provenance_records(
72	        since_str,
73	        args.project.as_deref(),
74	        args.dev.as_deref(),
75	    )
76	    .context("failed to query provenance records")?;
77	
78	    let stats = stats_from_records(&records, since_str)
79	        .context("failed to gather audit stats")?;
80	
81	    let envelope = generate_slsa(&records, &stats).context("failed to generate SLSA attestation")?;
82	
83	    // Determine output directory.
84	    let out_dir = std::path::PathBuf::from(
85	        args.output
86	            .as_deref()
87	            .unwrap_or("codeflow-audit"),
88	    );
89	    std::fs::create_dir_all(&out_dir)
90	        .with_context(|| format!("failed to create output dir: {}", out_dir.display()))?;
91	
92	    // Write file named {unix-timestamp}-slsa-provenance.json
93	    let ts = chrono::Utc::now().format("%Y%m%dT%H%M%SZ").to_string();
94	    let filename = format!("{}-slsa-provenance.json", ts);
95	    let out_path = out_dir.join(&filename);
96	
97	    let json_str =
98	        serde_json::to_string_pretty(&envelope).context("failed to serialize envelope")?;
99	    std::fs::write(&out_path, &json_str)
100	        .with_context(|| format!("failed to write: {}", out_path.display()))?;
101	
102	    if args.json {
103	        // Machine-readable summary: envelope path + stats.
104	        let summary = serde_json::json!({
105	            "format": "slsa",
106	            "output_file": out_path.to_string_lossy(),
107	            "range": args.range,
108	            "total_provenance": stats.total_provenance,
109	            "total_cost_usd": stats.total_cost_usd,
110	            "date_from": stats.date_range.0,
111	            "date_to":   stats.date_range.1,
112	        });
113	        println!("{}", serde_json::to_string_pretty(&summary)?);
114	        return Ok(0);
115	    }
116	
117	    // Human-readable output.
118	    println!("{}", "Codeflow Audit Export".bold());
119	    println!("{}", "─".repeat(50));
120	    println!(
121	        "  Format:    {}",
122	        "SLSA Provenance v1.0".cyan().bold()
123	    );
124	    println!(
125	        "  Range:     {} → {}",
126	        args.range,
127	        since_str.unwrap_or("epoch")
128	    );
129	    println!(
130	        "  Records:   {}",
131	        stats.total_provenance.to_string().yellow()
132	    );
133	    println!(
134	        "  Cost:      {}",
135	        format!("${:.4}", stats.total_cost_usd).yellow()
136	    );
137	    println!();
138	    println!(
139	        "  Output:    {}",
140	        out_path.display().to_string().green().bold()
141	    );
142	
143	    if stats.total_provenance == 0 {
144	        println!();
145	        println!(
146	            "  {}",
147	            "No provenance records found for this range.".dimmed()
148	        );
149	        println!(
150	            "  {}",
151	            "Run sessions with RTK_CODEFLOW=1 to start recording.".dimmed()
152	        );
153	    }
154	
155	    Ok(0)
156	}
157	
158	// ── Coming-soon stubs ─────────────────────────────────────────────────────────
159	
160	fn run_coming_soon(fmt: &AuditFormat) -> Result<i32> {
161	    println!(
162	        "{} export is coming in a future release.",
163	        fmt.label().yellow().bold()
164	    );
165	    println!(
166	        "Currently supported: {}",
167	        "slsa".cyan()
168	    );
169	    Ok(0)
170	}
