1	//! Shared types and helpers for compliance export formats.
2	//!
3	//! Provides `AuditRequest`, `AuditFormat`, `AuditStats`, and helper
4	//! functions that query provenance.db and cost.db for a given date range.
5	
6	use anyhow::{Context, Result};
7	use std::path::PathBuf;
8	
9	use crate::core::cost_store::CostStore;
10	use crate::core::provenance::{ProvenanceRecord, ProvenanceStore};
11	
12	// ── Public types ──────────────────────────────────────────────────────────────
13	
14	/// Specifies which compliance export format to produce.
15	#[derive(Debug, Clone, PartialEq)]
16	pub enum AuditFormat {
17	    Slsa,
18	    CycloneDx,
19	    Soc2,
20	    EuAiAct,
21	    All,
22	}
23	
24	impl AuditFormat {
25	    /// Parse from a CLI string value (case-insensitive).
26	    pub fn from_str(s: &str) -> Option<Self> {
27	        match s.to_lowercase().as_str() {
28	            "slsa" => Some(Self::Slsa),
29	            "cyclonedx" => Some(Self::CycloneDx),
30	            "soc2" => Some(Self::Soc2),
31	            "eu-ai-act" | "euaiact" => Some(Self::EuAiAct),
32	            "all" => Some(Self::All),
33	            _ => None,
34	        }
35	    }
36	
37	    /// Human-readable label for display.
38	    pub fn label(&self) -> &'static str {
39	        match self {
40	            Self::Slsa => "SLSA Provenance v1.0",
41	            Self::CycloneDx => "CycloneDX SBOM",
42	            Self::Soc2 => "SOC 2 Type II",
43	            Self::EuAiAct => "EU AI Act Annex IV",
44	            Self::All => "All Formats",
45	        }
46	    }
47	}
48	
49	/// Parameters for an audit export run.
50	#[allow(dead_code)]
51	pub struct AuditRequest {
52	    pub format: AuditFormat,
53	    pub range_days: u32,
