71	/// Aggregated statistics gathered from the local databases.
72	#[allow(dead_code)]
73	#[derive(Debug, Clone)]
74	pub struct AuditStats {
75	    pub total_provenance: u64,
76	    pub total_cost_usd: f64,
77	    pub quality_findings: u64,
78	    /// (from_rfc3339, to_rfc3339)
79	    pub date_range: (String, String),
80	}
81	
82	// ── Date range helpers ────────────────────────────────────────────────────────
83	
84	/// Convert a range specifier string to a start ISO-8601 timestamp (UTC).
85	///
86	/// Supported values: "30d", "90d", "1y", "all"
87	/// Returns `None` for "all" (no lower bound).
88	pub fn range_to_since(range: &str) -> Option<String> {
89	    let days: i64 = match range.to_lowercase().as_str() {
90	        "all" => return None,
91	        "30d" => 30,
92	        "90d" => 90,
93	        "1y" => 365,
94	        other => {
95	            let n = if let Some(stripped) = other.strip_suffix('d') {
96	                stripped.parse::<i64>().ok()?
97	            } else {
98	                other.parse::<i64>().ok()?
99	            };
100	            if n <= 0 {
101	                return None;
102	            }
103	            n
104	        }
105	    };
106	    let since = chrono::Utc::now() - chrono::Duration::days(days);
107	    Some(since.to_rfc3339())
108	}
109	
110	/// Convert a `range_days` integer to an RFC3339 start timestamp.
111	pub fn days_to_since(days: u32) -> String {
112	    let since = chrono::Utc::now() - chrono::Duration::days(days as i64);
113	    since.to_rfc3339()
114	}
115	
116	// ── Database query helpers ────────────────────────────────────────────────────
117	
118	/// Query all provenance records within a date range.
119	///
120	/// `since_rfc3339` is an inclusive lower bound; `None` returns all records.
121	pub fn query_provenance_records(
122	    since_rfc3339: Option<&str>,
123	    project_filter: Option<&str>,
124	    dev_filter: Option<&str>,
125	) -> Result<Vec<ProvenanceRecord>> {
126	    let store = match ProvenanceStore::new() {
127	        Ok(s) => s,
128	        Err(_) => return Ok(Vec::new()), // DB does not exist yet — empty export
129	    };
130	
131	    store
132	        .query_range(since_rfc3339, project_filter, dev_filter)
133	        .context("failed to query provenance records")
134	}
135	
136	/// Compute stats from already-fetched provenance records (avoids double DB query).
137	pub fn stats_from_records(
138	    records: &[ProvenanceRecord],
139	    since_rfc3339: Option<&str>,
140	) -> Result<AuditStats> {
141	    let total_provenance = records.len() as u64;
142	
143	    let total_cost_usd = match CostStore::new() {
144	        Ok(store) => {
145	            if let Some(since) = since_rfc3339 {
146	                store.total_cost_since(since).unwrap_or(0.0)
147	            } else {
148	                store.total_cost(None).unwrap_or(0.0)
149	            }
150	        }
151	        Err(_) => 0.0,
152	    };
153	
154	    let now = chrono::Utc::now().to_rfc3339();
155	    let from = since_rfc3339.unwrap_or("epoch").to_string();
156	
157	    Ok(AuditStats {
158	        total_provenance,
159	        total_cost_usd,
160	        quality_findings: 0,
161	        date_range: (from, now),
162	    })
163	}
164	
165	/// Gather aggregate statistics from both databases for the given range.
166	#[allow(dead_code)]
167	pub fn gather_stats(
168	    since_rfc3339: Option<&str>,
169	    project_filter: Option<&str>,
170	    dev_filter: Option<&str>,
171	) -> Result<AuditStats> {
172	    let records = query_provenance_records(since_rfc3339, project_filter, dev_filter)?;
173	    let total_provenance = records.len() as u64;
174	
175	    let total_cost_usd = match CostStore::new() {
176	        Ok(store) => {
177	            if let Some(since) = since_rfc3339 {
178	                store.total_cost_since(since).unwrap_or(0.0)
179	            } else {
180	                store.total_cost(None).unwrap_or(0.0)
181	            }
182	        }
183	        Err(_) => 0.0,
184	    };
185	
186	    let now = chrono::Utc::now().to_rfc3339();
187	    let from = since_rfc3339.unwrap_or("epoch").to_string();
188	
189	    Ok(AuditStats {
190	        total_provenance,
191	        total_cost_usd,
192	        quality_findings: 0, // Phase 5 stub — quality gate integration is post-MVP
193	        date_range: (from, now),
194	    })
195	}
