//! Data export logic for codeflow Phase 6.
//!
//! Supports three formats: JSON, CSV, HTML dashboard.

use anyhow::{Context, Result};
use serde::Serialize;

use crate::compliance::report_common::query_provenance_records;
use crate::core::cost_store::CostStore;
use crate::core::provenance::ProvenanceRecord;

// ── Public types ──────────────────────────────────────────────────────────────

/// Aggregated cost by model.
#[derive(Debug, Clone, Serialize)]
pub struct ModelCostSummary {
    pub model_id: String,
    pub total_usd: f64,
    pub total_tokens: u64,
}

/// High-level statistics for the exported range.
#[derive(Debug, Clone, Serialize)]
pub struct ExportStats {
    pub total_files: u64,
    pub total_cost_usd: f64,
    pub ai_pct: f64,
    pub top_model: String,
    /// (from_rfc3339, to_rfc3339)
    pub date_range: (String, String),
}

// ── Data loading ──────────────────────────────────────────────────────────────

/// Load provenance records and cost summaries for a given range / project filter.
///
/// Both databases are opened independently; a missing DB yields empty data with a hint message.
pub fn load_export_data(
    since_rfc3339: Option<&str>,
    project: Option<&str>,
) -> Result<(Vec<ProvenanceRecord>, Vec<ModelCostSummary>, ExportStats)> {
    // Provenance records — graceful empty on missing DB.
    let records = query_provenance_records(since_rfc3339, project, None)
        .context("failed to query provenance records")?;

    // Cost summaries by model — graceful empty on missing DB.
    let cost_summaries: Vec<ModelCostSummary> = match CostStore::new() {
        Ok(store) => store
            .summarize_by_model()
            .unwrap_or_default()
            .into_iter()
            .map(|s| ModelCostSummary {
                model_id: s.key,
                total_usd: s.total_cost_usd,
                total_tokens: s.input_tokens + s.output_tokens,
            })
            .collect(),
        Err(_) => Vec::new(),
    };

    let stats = build_stats(&records, &cost_summaries, since_rfc3339);
    Ok((records, cost_summaries, stats))
}

fn build_stats(
    records: &[ProvenanceRecord],
    costs: &[ModelCostSummary],
    since_rfc3339: Option<&str>,
) -> ExportStats {
    let total_files = records.len() as u64;
    let total_cost_usd: f64 = costs.iter().map(|c| c.total_usd).sum();

    let ai_count = records
        .iter()
        .filter(|r| matches!(r.contributor_type, crate::core::provenance::ContributorType::Ai))
        .count();
    let ai_pct = if total_files > 0 {
        (ai_count as f64 / total_files as f64) * 100.0
    } else {
        0.0
    };

    let top_model = costs
        .iter()
        .max_by(|a, b| a.total_usd.partial_cmp(&b.total_usd).unwrap_or(std::cmp::Ordering::Equal))
        .map(|c| c.model_id.clone())
        .unwrap_or_else(|| "none".to_string());

    let now = chrono::Utc::now().to_rfc3339();
    let from = since_rfc3339.unwrap_or("epoch").to_string();

    ExportStats {
        total_files,
        total_cost_usd,
        ai_pct,
        top_model,
        date_range: (from, now),
    }
}

// ── JSON export ───────────────────────────────────────────────────────────────

pub fn export_json(
    provenance: &[ProvenanceRecord],
    costs: &[ModelCostSummary],
    stats: &ExportStats,
) -> Result<String> {
    let payload = serde_json::json!({
        "schema": "rtk-codeflow-export-v1",
        "generated_at": chrono::Utc::now().to_rfc3339(),
        "stats": stats,
        "cost_by_model": costs,
        "provenance": provenance,
    });
    serde_json::to_string_pretty(&payload).context("failed to serialize JSON export")
}

// ── CSV export ────────────────────────────────────────────────────────────────

pub fn export_csv(provenance: &[ProvenanceRecord]) -> Result<String> {
    let mut out = String::new();
    // Header
    out.push_str(
        "id,model_id,model_version,file_path,start_line,end_line,contributor_type,developer_id,session_id,timestamp\n",
    );
    for r in provenance {
        let id = r.id.map(|n| n.to_string()).unwrap_or_default();
        // Escape fields that may contain commas/quotes
        let fields = [
            id.as_str(),
            &r.model_id,
            &r.model_version,
            &r.file_path,
            &r.start_line.to_string(),
            &r.end_line.to_string(),
            r.contributor_type.as_str(),
            &r.developer_id,
            &r.session_id,
            &r.timestamp,
        ];
        let row: Vec<String> = fields.iter().map(|f| csv_escape(f)).collect();
        out.push_str(&row.join(","));
        out.push('\n');
    }
    Ok(out)
}

fn csv_escape(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

